Feature: Display Snackbars for Record Submission

Scenario: Display snackbar when child records are delayed created

Given auto-create child records is enabled
And the user submits a parent record for approval
When the child records are delayed in creation
Then display snackbar message "{record} submitted for approval. Linked {record(s)} will be created in the {database name} when this {record} is approved."

Python:

from behave import given, when, then

@given('auto-create child records is enabled')
def step_impl(context):
    context.auto_create_enabled = True

@given('the user submits a parent record for approval')
def step_impl(context):
    context.parent_record = "ParentRecord"
    context.database_name = "ChildDatabase"

@when('the child records are delayed in creation')
def step_impl(context):
    context.child_records_delayed = True

@then('display snackbar message "{record} submitted for approval. Linked {record(s)} will be created in the {database name} when this {record} is approved."')
def step_impl(context):
    record = context.parent_record
    records = "ChildRecord(s)"
    database_name = context.database_name
    expected_message = f"{record} submitted for approval. Linked {records} will be created in the {database_name} when this {record} is approved."
    assert expected_message == f"{record} submitted for approval. Linked {records} will be created in the {database_name} when this {record} is approved."

