Feature: Cancel Selection in Footer

Scenario: Deselect all selected requests using the Cancel action

Given a list of items with checkboxes
And at least one item's checkbox is selected
When the Bulk Action footer bar is displayed
And the user clicks the 'Cancel' action on the right side of the footer
Then all selected items are deselected
And all checkboxes are displayed as selectable

Python:

from behave import given, when, then

@given('a list of items with checkboxes')
def step_given_list_of_items(context):
    context.items = [{'selected': False} for _ in range(5)]

@given('at least one item\'s checkbox is selected')
def step_given_item_selected(context):
    context.items[0]['selected'] = True

@when('the Bulk Action footer bar is displayed')
def step_when_footer_displayed(context):
    context.footer_displayed = True

@when('the user clicks the \'Cancel\' action on the right side of the footer')
def step_when_user_clicks_cancel(context):
    if context.footer_displayed:
        for item in context.items:
            item['selected'] = False

@then('all selected items are deselected')
def step_then_items_deselected(context):
    assert all(not item['selected'] for item in context.items)

@then('all checkboxes are displayed as selectable')
def step_then_checkboxes_selectable(context):
    assert all('selectable' in item for item in context.items)

