Feature: Exclude Deleted Documents from Q&A

Scenario: Ensure deleted documents are not used in answers

Given a document repository with documents
And a document is marked as deleted
When a user asks a question
Then the answer should not include information from the deleted document

Python:

from behave import given, when, then

@given('a document repository with documents')
def step_given_document_repository(context):
    context.documents = {'doc1': 'content1', 'doc2': 'content2'}
    context.deleted_documents = []

@given('a document is marked as deleted')
def step_given_document_marked_deleted(context):
    context.deleted_documents.append('doc1')

@when('a user asks a question')
def step_when_user_asks_question(context):
    context.question = "What is the content?"
    context.answer = generate_answer(context.question, context.documents, context.deleted_documents)

@then('the answer should not include information from the deleted document')
def step_then_answer_excludes_deleted(context):
    assert 'content1' not in context.answer

def generate_answer(question, documents, deleted_documents):
    available_docs = {k: v for k, v in documents.items() if k not in deleted_documents}
    return " ".join(available_docs.values())

