Feature: Bulk Review of Resource Download Requests

Scenario: Select requests with the same template for bulk review

Given there are multiple resource download requests
And all requests are tied to the same template
And each request has a different "Needed until" value
When I select the requests for bulk review
Then the requests are successfully selected for bulk review

Python:

from behave import given, when, then

@given('there are multiple resource download requests')
def step_impl(context):
    context.requests = [
        {'template': 'TemplateA', 'needed_until': '2023-12-01'},
        {'template': 'TemplateA', 'needed_until': '2023-12-05'},
        {'template': 'TemplateA', 'needed_until': None}
    ]

@given('all requests are tied to the same template')
def step_impl(context):
    assert all(req['template'] == 'TemplateA' for req in context.requests)

@given('each request has a different "Needed until" value')
def step_impl(context):
    needed_until_values = [req['needed_until'] for req in context.requests]
    assert len(set(needed_until_values)) == len(context.requests)

@when('I select the requests for bulk review')
def step_impl(context):
    context.selected_requests = context.requests

@then('the requests are successfully selected for bulk review')
def step_impl(context):
    assert context.selected_requests == context.requests

