Feature: Detect and Modify Non-Matching Params in Bulk Response

Scenario: Modify response when requests have non-matching params

Given a BulkReview component with multiple requests
And each request has a set of params
When the params of the requests are compared
And not all requests have matching params
Then the bulk response section is modified

Python:

from behave import given, when, then

@given('a BulkReview component with multiple requests')
def step_given_bulk_review_component(context):
    context.requests = [
        {'params': {'id': 1, 'value': 'A'}},
        {'params': {'id': 2, 'value': 'B'}}
    ]

@given('each request has a set of params')
def step_given_requests_have_params(context):
    assert all('params' in request for request in context.requests)

@when('the params of the requests are compared')
def step_when_compare_params(context):
    context.param_sets = [request['params'] for request in context.requests]

@when('not all requests have matching params')
def step_when_check_non_matching_params(context):
    context.non_matching = len(set(frozenset(params.items()) for params in context.param_sets)) > 1

@then('the bulk response section is modified')
def step_then_modify_bulk_response(context):
    assert context.non_matching
    context.modified_response = "Response modified due to non-matching params"

