Feature: Bulk Approval of Requests

Scenario: Select pending requests for bulk approval

Given a list of requests with checkboxes
And some requests are marked as Pending
When a Pending request checkbox is selected
Then only checkboxes for related Pending requests remain selectable

Python:

from behave import given, when, then

@given('a list of requests with checkboxes')
def step_given_list_of_requests(context):
    context.requests = [
        {'id': 1, 'status': 'Pending'},
        {'id': 2, 'status': 'Approved'},
        {'id': 3, 'status': 'Pending'},
        {'id': 4, 'status': 'Rejected'}
    ]

@given('some requests are marked as Pending')
def step_given_pending_requests(context):
    context.pending_requests = [req for req in context.requests if req['status'] == 'Pending']

@when('a Pending request checkbox is selected')
def step_when_pending_request_selected(context):
    context.selected_request = context.pending_requests[0]

@then('only checkboxes for related Pending requests remain selectable')
def step_then_only_related_pending_selectable(context):
    selectable_requests = [req for req in context.requests if req['status'] == 'Pending']
    assert context.selected_request in selectable_requests
    assert all(req in selectable_requests for req in context.pending_requests)

